import { http, HttpResponse } from 'msw'
import queue from './fixtures/GET_queue.json'
import detail from './fixtures/GET_customer_detail.json'
import noOffer from './fixtures/GET_customer_no_offer.json'
import summary from './fixtures/GET_summary.json'
import catalog from './fixtures/GET_catalog.json'
import action from './fixtures/POST_action.json'
import score from './fixtures/POST_score.json'
import validationError from './fixtures/ERROR_validation.json'
import leakageError from './fixtures/ERROR_leakage.json'

/**
 * These fixtures are GENERATED by `python -m src.api_fixtures` from the real
 * model, catalog and knowledge base — they are not hand-written. Re-run that
 * command after any backend change and the mocks move with it.
 */
export const handlers = [
  http.get('/api/queue', () => HttpResponse.json(queue)),
  http.get('/api/summary', () => HttpResponse.json(summary)),
  http.get('/api/catalog', () => HttpResponse.json(catalog)),
  http.get('/api/customers/:id', ({ params }) =>
    HttpResponse.json(params.id === noOffer.customer_id ? noOffer : detail),
  ),
  http.post('/api/customers/:id/action', () => HttpResponse.json(action.response_example)),
  http.post('/api/score', () => HttpResponse.json(score.response_example)),
]

/** Opt-in handlers for building and testing failure screens. */
export const failureHandlers = {
  validation: http.get('/api/queue', () => HttpResponse.json(validationError, { status: 422 })),
  leakage: http.get('/api/queue', () => HttpResponse.json(leakageError, { status: 400 })),
  serverError: http.get('/api/queue', () => new HttpResponse(null, { status: 500 })),
}
